if type(Dm)==Itc[1440]then
local Em=tonumber(Dm.amount)or 0
if Dm.type==Itc[1650]then
Am=Am+math.abs(Em)*Bm*I.pearlValue
elseif Dm.type==Itc[1651]then
local Fm,Gm=pcall(O.rewardValue,Dm.reward)
if Fm then
Am=Am+(tonumber(Gm)or 0)
end
elseif Dm.type==Itc[1652]then
Am=Am+Em*eb.STARFALL_GEMS
elseif Dm.type==Itc[1653]then
Am=Am+Em*100
end
end
end
if ym.option_type==Itc[1654]then
Am=Am+eb.HARD_GEMS
end
if ym.weather then
local Hm=ym.weather~=eb.weatherNow()
if Hm and ym.weather==Itc[1655]then
Am=Am+eb.STARFALL_GEMS
end
local Im=eb.board()
if Hm and Im and ym.weather~=Itc[1624]and not Im.weathers[ym.weather]then
Am=Am+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
