return 0
end
local YI,ZI=0,0
for _I,aJ in pairs(TI._core_damage_type_buffs or{})do
if WI[aJ.damage_type]then
YI=YI+(tonumber(aJ.mul)or 0)+(tonumber(aJ.add_upg)or 0)*0.01+(tonumber(aJ.pen)or 0)*0.001
ZI=ZI+(tonumber(aJ.crit)or 0)
