end
if#JR==0 then
P.pickNote.autoFuseXp=Itc[2174]
return
end
if os.time()-(tonumber(I.fuseXpOnAt)or 0)<30 then
P.pickNote.autoFuseXp=Itc[2175]
return
end
P.pickNote.autoFuseXp=nil
if j.req.back.fuseXp and M.now()<j.req.back.fuseXp then
return
end
P.fuseBatch=P.fuseBatch or 50
local MR,NR,OR=0,0,{}
while j.alive and MR<10 do
if MR>0 then
local PR,QR,RR=P.xpFodder(GR.collection:get_unit_by_uuid(I.fuseXpUnit)or HR)
JR,LR={},RR
for SR,TR in ipairs(PR)do
if not OR[TR.uuid]then
table.insert(JR,TR)
end
end
if LR<=0 or#JR==0 then
break
end
end
local UR={}
for VR=1,math.min(P.fuseBatch,#JR)do
table.insert(UR,JR[VR].uuid)
end
local WR=tonumber((GR.collection:get_unit_by_uuid(I.fuseXpUnit)or HR).xp)or 0
local XR=M.now()
local YR,ZR=j.request(Itc[2176],Itc[2177],I.fuseXpUnit,UR)
