R.add(string.format(Itc[2178],#UR,IR),#UR,Itc[2179],string.format(Itc[2180],M.fmt(_R-WR)))
j.log(1,Itc[1637],string.format(Itc[2181],#UR,IR,M.fmt(_R-WR),db.level(GR.collection:get_unit_by_uuid(I.fuseXpUnit)or HR)))
elseif#UR>20 then
