j.log(1,Itc[1637],string.format(Itc[2182],#UR,tostring(j.gameSaid(XR)or(YR and ZR)or Itc[1704])))
else
local cS=j.gameSaid(XR)
P.pickNote.autoFuseXp=Itc[2183]..tostring(cS or(YR and ZR)or Itc[1704])..Itc[2184]
j.log(1,Itc[1637],Itc[2185]..tostring(cS or(YR and ZR)or Itc[1704]))
j.backoff(Itc[2176],1800)
