W.INF_CAP=80
function W.evaluate(Qmb,Rmb)
local Smb=W.run(Qmb,Rmb,{hpMul=1})
local Tmb={won=Smb.won,wave=Smb.wave,minutes=Smb.t/60,aliveAt=Smb.aliveAt,total=Qmb.total,at=os.time()}
if Qmb.infinite and W.unbound(Qmb.ld)then
Tmb.p=1
Tmb.margin=Smb.won and string.format(Itc[2642],Qmb.total)or string.format(Itc[2643],Smb.wave,Smb.t/60)
elseif Smb.won then
local Umb=W.run(Qmb,Rmb,{hpMul=1.3})
Tmb.p=Umb.won and 0.92 or 0.7
Tmb.margin=Umb.won and Itc[2644]or Itc[2645]
else
local Vmb=W.run(Qmb,Rmb,{hpMul=0.75})
Tmb.p=Vmb.won and 0.25 or 0.05
Tmb.margin=Vmb.won and string.format(Itc[2646],Smb.wave)or string.format(Itc[2647],Smb.wave,Qmb.total)
if not Vmb.won then
local Wmb=W.run(Qmb,Rmb,{hpMul=0.25})
if not Wmb.won then
Tmb.p,Tmb.hopeless=0.005,true
Tmb.margin=string.format(Itc[2648],Smb.wave,Qmb.total)
end
end
end
return Tmb
end
function W.trust(Xmb,Ymb)
local Zmb=Xmb.cal or{}
if type(Zmb.alive)~=Itc[1440]or Zmb.teamSig~=W.sig((function()
local _mb={}
for anb,bnb in ipairs(Ymb)do
table.insert(_mb,bnb.u)
end
return _mb
end)())then
return nil
end
if Xmb.key==Itc[1734]and not Zmb.aliveLvl then
return nil
end
if Zmb.aliveLvl and Xmb.ld and Xmb.ld.id and Zmb.aliveLvl~=tostring(Xmb.ld.id)..(eb.is(Xmb.ld.id)and(Itc[2649]..tostring(Xmb.ld.map))or Itc[369])then
return nil
end
local cnb=W.run(Xmb,Ymb,{hpMul=1})
local dnb,enb,fnb=0,0,0
for gnb=3,math.min(cnb.wave,tonumber(Zmb.lastWave)or 99)do
local hnb=tonumber(Zmb.alive[tostring(gnb)])
local inb=cnb.aliveAt[gnb]
if hnb and inb and hnb>0 then
dnb=dnb+hnb
enb=enb+inb
fnb=fnb+1
end
end
if fnb<2 or enb<=0 then
return nil
end
local jnb=dnb/enb
return{ratio=jnb,ok=jnb>=0.75 and jnb<=1.33,waves=fnb}
end
