local qnb,rnb=pcall(H.USC.calculate_level,pnb,tonumber(onb.xp)or 0)
if qnb and(tonumber(rnb)or 0)>=W.GROWN_LEVEL then
lnb[pnb]=true
mnb=mnb+1
