end
table.sort(Inb,function(Onb,Pnb)
return Onb.sc>Pnb.sc
end)
table.sort(Jnb,function(Qnb,Rnb)
return Qnb.sc>Rnb.sc
end)
local Snb={}
for Tnb=1,math.min(10,#Inb)do
table.insert(Snb,Inb[Tnb].u)
end
local Unb,Vnb={},{}
for Wnb=11,#Inb do
local Xnb=N.rows(Inb[Wnb].u.unit_id)
for Ynb=0,Xnb.max do
if Xnb[Ynb]and Xnb[Ynb].atk and N.attackInfo(Xnb[Ynb].atk,Xnb[Ynb].range).dot>0 then
table.insert(Ynb==0 and Unb or Vnb,Inb[Wnb].u)
break
end
end
end
for Znb=1,math.min(4,#Unb)do
table.insert(Snb,Unb[Znb])
end
for _nb=1,math.min(2,#Vnb)do
table.insert(Snb,Vnb[_nb])
end
for aob=1,math.min(3,#Jnb)do
table.insert(Snb,Jnb[aob].u)
end
local bob={}
for cob=11,#Inb do
