table.insert(gob,job)
end
local lob,mob=tonumber(kob and kob.cd)or 0,tonumber((H.Units[job.unit_id]or{}).cost)or 0
if lob>0 and mob>0 and N.range(job,0)>=15 then
local nob=N.attackInfo(kob.atk,kob.range)
