table.insert(Prb,Rrb.unit_id)
end
J.simTeam[prb.key]={uuids=Erb.winTeam,names=Orb,ids=Prb,won=true,wave=wrb.total,better=W.sig(Grb)~=Brb.sig,cur={won=Brb.won,wave=Brb.wave},at=os.time(),label=prb.label,base=Brb.sig,why=Itc[2661]}
j.log(1,Itc[2655],string.format(Itc[2662],prb.label,table.concat(Orb,Itc[1536]),Nrb and string.format((Mrb.ratio or 0)<0.1 and Itc[2663]or Itc[2664],Mrb.ratio or 0)or string.format(Itc[2665],Lrb.wave),Erb.winTeamN or 1))
return Brb
end
end
end
if I.simTeams and qrb then
local Srb,Trb,Urb,Vrb,Wrb=pcall(W.bestTeam,wrb,xrb,W.pool(vrb,wrb),rrb)
if Srb and Trb then
local Xrb=W.sig(Trb)~=Brb.sig
if Xrb and Brb.won and(Brb.p or 0)>=0.92 then
local Yrb={}
for Zrb,_rb in ipairs(Trb)do
table.insert(Yrb,N.name(_rb.unit_id))
end
j.log(1,Itc[2655],string.format(Itc[2666],prb.label,table.concat(Yrb,Itc[1536])))
Trb,Xrb=xrb,false
end
local asb=Itc[369]
