if dsb>bsb or(dsb==bsb and esb>csb)or fsb then
asb=string.format(Itc[2667],dsb,bsb)..(fsb and string.format(Itc[2668],#Trb,#xrb)or Itc[369])
else
local gsb={}
for hsb,isb in ipairs(Trb)do
