j.log(1,Itc[2655],string.format(Itc[2672],prb.label,jsb.won and Itc[1782]or(Itc[2673]..jsb.wave),table.concat(lsb,Itc[1536]),Xrb and(string.format(Itc[2674],Vrb,Urb.won and Itc[1782]or Itc[1783],Urb.wave,Wrb.won and Itc[1782]or Itc[1783],Wrb.wave)..asb)or Itc[2675]))
local rsb={}
