elseif Fsb.wave>jsb.wave then
usb=string.format(Itc[2678],prb.label,Fsb.wave,jsb.wave)
elseif Fsb.won and jsb.won and Fsb.t<jsb.t-6 then
usb=string.format(Itc[2679],prb.label,(jsb.t-Fsb.t)/60)
else
usb=jsb.won and(Itc[2680]..prb.label..Itc[2681])or(Itc[2682]..prb.label)
