local CRb=math.max(0.2,1/BRb.n)
local function DRb(ERb)
if#ERb==0 then
return nil
end
table.sort(ERb)
return ERb[math.ceil(#ERb/2)]
end
local function FRb(GRb,HRb)
if HRb then
BRb[GRb]=BRb[GRb]and(BRb[GRb]+(HRb-BRb[GRb])*CRb)or HRb
end
